from sympy.solvers.solveset import linsolve


class Cable:
    """
    Cables are structures in engineering that support
    the applied transverse loads through the tensile resistance
    developed in its cables.

    Examples
    ========
   
    >>> from sympy.physics.continuum_mechanics.cable import Cable
    >>> c = Cable(('A', 0, 10), ('B', 10, 10), 5)
    """

    def __init__(self, support_1, support_2, length):
        """
        """
        self._support_1 = support_1
        self._support_2 = support_2
        self._support_1_position = (support_1[1], support_2[2])
        self._support_2_position = (support_2[1], support_2[2])

        self._length = length
        self._left_support = None
        self._right_support = None
        self._loads = {}

    @property
    def left_support(self):
        """The left support of the cable."""
        return self._left_support

    @property
    def right_support(self):
        """The right support of the cable."""
        return self._right_support

    @property
    def loads(self):
        """The loads acting on the cable."""
        return self._loads

    @property
    def length(self):
        """The length of the cable."""
        return self._length

    
    
